import re

def parse(lines):
    blocks = []
    skip = []
    cur = None
    last = None
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        m = re.match(r'^Job Id:\s*(?P<id>\S.*)$', l)
        if m:
            cur = {'name': 'job', 'kind': 'kv', 'lines': [i], 'records': [{'Job Id': m.group('id').strip()}]}
            blocks.append(cur)
            last = None
            continue
        if cur is not None:
            if l.startswith('\t') and last is not None:
                cur['records'][0][last] += l.strip()
                cur['lines'].append(i)
                continue
            m = re.match(r'^\s+(?P<key>[A-Za-z_][\w.]*)\s+=\s?(?P<value>.*)$', l)
            if m:
                last = m.group('key')
                cur['records'][0][last] = m.group('value').rstrip()
                cur['lines'].append(i)
                continue
        if re.match(r'^\s*(\[[^\]]*\][$#]|\S*[$#]\s)', l) or re.match(r'^\s*\S*[$#]\s*$', l):
            skip.append(i)
            last = None
    return {'blocks': blocks, 'skip': skip}
